PRAGMA foreign_keys = ON;
CREATE TABLE admins (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_sessions (id TEXT PRIMARY KEY, admin_id INTEGER NOT NULL REFERENCES admins(id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts (key_hash TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, window_started_at TEXT NOT NULL);
CREATE TABLE students (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, attendance_number INTEGER NOT NULL CHECK(attendance_number > 0), class_name TEXT NOT NULL, qr_token_hash TEXT UNIQUE, has_voted INTEGER NOT NULL DEFAULT 0 CHECK(has_voted IN (0,1)), voted_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(class_name, attendance_number), CHECK((has_voted=0 AND voted_at IS NULL) OR (has_voted=1 AND voted_at IS NOT NULL)));
CREATE TABLE candidates (id INTEGER PRIMARY KEY AUTOINCREMENT, candidate_number INTEGER NOT NULL UNIQUE, chairman_name TEXT NOT NULL, vice_chairman_name TEXT NOT NULL, photo_url TEXT NOT NULL DEFAULT '', vision TEXT NOT NULL DEFAULT '', mission TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE votes (id INTEGER PRIMARY KEY AUTOINCREMENT, candidate_id INTEGER NOT NULL REFERENCES candidates(id) ON DELETE RESTRICT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE election_settings (id INTEGER PRIMARY KEY CHECK(id=1), election_name TEXT NOT NULL, school_name TEXT NOT NULL, start_at TEXT, end_at TEXT, status TEXT NOT NULL CHECK(status IN ('DRAFT','OPEN','CLOSED')), show_results INTEGER NOT NULL DEFAULT 1, quick_count_enabled INTEGER NOT NULL DEFAULT 1, quick_count_mode TEXT NOT NULL DEFAULT 'PERCENTAGE_ONLY' CHECK(quick_count_mode IN ('OFF','PARTICIPATION_ONLY','PERCENTAGE_ONLY','FULL')), quick_count_refresh_interval INTEGER NOT NULL DEFAULT 5 CHECK(quick_count_refresh_interval BETWEEN 3 AND 60), show_candidate_photos INTEGER NOT NULL DEFAULT 1, show_final_winner INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER REFERENCES admins(id) ON DELETE SET NULL, action TEXT NOT NULL, target TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_students_status ON students(has_voted); CREATE INDEX idx_students_class ON students(class_name); CREATE INDEX idx_votes_candidate ON votes(candidate_id);
CREATE TRIGGER no_vote_delete_open BEFORE DELETE ON votes WHEN (SELECT status FROM election_settings WHERE id=1)='OPEN' BEGIN SELECT RAISE(ABORT,'votes_locked_during_open_election'); END;
INSERT INTO election_settings(id,election_name,school_name,status) VALUES(1,'Pemilihan Ketua & Wakil Ketua OSIS','Nama Sekolah','DRAFT');
